55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const isInsurableItemType = (type: string): type is InsurableItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  isInsurableItemType(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	const areAllSameType = ([first, ...rest]: Item[]): boolean =>
87	  rest.every((item) => item.type === first?.type);
88	
89	// The block rule is currently evaluated over the whole item list. Grouping by
90	// type comes with the pending 3-runes-plus-3-moonstones test.
91	const isBlock = (items: Item[]): boolean =>
92	  items.length === BLOCK_SIZE && areAllSameType(items);
93	
94	const basePremiumForItems = (items: Item[]): number =>
95	  isBlock(items)
96	    ? BLOCK_BASE_PREMIUM
97	    : items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
98	
99	const withInitialAssessmentSurcharge = (basePremium: number): number =>
100	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
101	
102	const quotePremium = (items: Item[]): number =>
103	  Math.round(
104	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
105	  );
106	
107	const runStep = (step: Step): StepResult => {
108	  if (step.op === "quote") return { premium: quotePremium(step.items) };
109	  throw new Error(`Unsupported step: ${step.op}`);
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResult => ({
113	  results: scenario.steps.map(runStep),
114	});
