const areAllSameType = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0]?.type);

// A block is not carved out of a larger group: the block price applies only
// when the group consists of exactly three alike components (7 runes cost
// 7 × 25, not 60 + 60 + 25). The rule is currently evaluated over the whole
// item list — grouping by type comes with the pending
// 3-runes-plus-3-moonstones test.
const qualifiesForBlockPrice = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && areAllSameType(items);

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);

const basePremiumForItems = (items: Item[]): number =>
  qualifiesForBlockPrice(items) ? BLOCK_BASE_PREMIUM : sumBasePremiums(items);
